actions.script:
// Only the key's hash is stored, so its token shows once, in a message on the next page (the log masks it).
const created=ec.service.sync().name('org.moqui.monitor.MonitorServices.create#IngestKey').parameters({source:source,expireDays:parseInt(expireDays || '90',10)}).call()
if (created.accessToken) ec.message.addPublic('New ingest key '+created.keyId+' for '+source+'. Copy it now; it is not shown again. token: '+created.accessToken,'warning')

sourceStatus = ec.service.sync().name('org.moqui.monitor.MonitorServices.get#SourceStatus').call()
sourceList = [];sourceNotices=[]
const published = new Map()
for (const [datasetId,timeField] of [['otel_spans','start'],['otel_logs','timestamp'],['otel_metrics','bucket_start']]) {
    try {
        const output=ec.service.sync().name('org.moqui.report.ReportServices.run#Query').parameters({query:{datasetId,from:'now-24h',thru:'now',aggregations:[
            {id:'source',type:'terms',role:'x-axis',params:{field:'source.id',size:100,missing:'(local)'}},
            {id:'service',type:'terms',role:'series',params:{field:'service.name',size:100,missing:'(unknown)'}},
            {id:'instance',type:'terms',role:'series',params:{field:'service.instance.id',size:100,missing:'(unknown)'}},
            {id:'latest',type:'max',role:'metric',params:{field:timeField}}
        ]}}).call()
        for (const frame of output.frames || []) {
            const fields=frame.fields || [],at=name=>fields.find(field=>field.name===name),source=at('source'),service=at('service'),instance=at('instance'),latest=at('latest')
            for (let row=0;source && row<source.values.length;row++) {
                const item={source:source.values[row],service:service && service.values[row],instance:instance && instance.values[row],lastSeen:latest && latest.values[row]}
                if (item.lastSeen != null) { const raw=String(item.lastSeen),date=new Date(/^\d+$/.test(raw)?Number(raw):raw);item.lastSeen=Number.isNaN(date.getTime())?null:date.toISOString() }
                const key=JSON.stringify([item.source,item.service,item.instance]),old=published.get(key)
                if (!old || String(item.lastSeen)>String(old.lastSeen)) published.set(key,item)
            }
        }
    } catch (error) { ec.logger.error('Source discovery '+datasetId+' failed: '+String(error));sourceNotices.push(datasetId+': '+String(error)) }
}
sourceList=Array.from(published.values()).slice(0,500).map(item=>Object.assign(item,{status:!item.lastSeen?'Unknown':new Date(item.lastSeen).getTime()>Date.now()-300000?'Recent telemetry':'No telemetry in five minutes'}))
ingestKeys = ec.service.sync().name('org.moqui.monitor.MonitorServices.list#IngestKeys').call().keys || []
counterList = Object.entries(sourceStatus.counters || {}).map(([name,value])=>({name,value}))
